 ladder:()=>`<div class="arc-art a-lad" aria-hidden="true"><span class="rail l"></span><span class="rail r"></span>${[0,1,2,3,4].map(k=>`<span class="rung" style="--k:${k}"></span>`).join('')}${[0,1,2,3,4].map(k=>`<b class="lv" style="--k:${k}">L${k+1}</b>`).join('')}<span class="star">★</span><b class="cl">★</b><b class="combo">×3 COMBO</b>${[[-18,-22],[16,-26],[-24,6],[22,10],[0,-30]].map(([x,y])=>`<s class="sp" style="--sx:${x}px;--sy:${y}px"></s>`).join('')}</div>`,
 speed:()=>`<div class="arc-art a-spd" aria-hidden="true"><span class="pv"></span><span class="pv p2"></span><span class="ring"></span><span class="sweep"></span><span class="hand"></span><div class="num"><b>30</b><b>60</b><b>120</b><small>SECONDS</small></div>${[[8,28,36,0],[2,52,44,.3],[10,76,30,.6],[182,36,36,.15],[176,60,44,.45],[184,84,30,.75]].map(([x,y,w,d])=>`<i class="ln" style="left:${x}px;top:${y}px;width:${w}px;--d:${d}s"></i>`).join('')}</div>`,
